        WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^_?mcp_' AND has_function_privilege('anon', p.oid, 'EXECUTE'))
        = (SELECT array_agg(x ORDER BY x COLLATE "C") FROM unnest(ARRAY['mcp_add_todo(text,bytea,text,text,text,text,text,text)', 'mcp_authorize_begin(text,text,text,text,text,text,text,text,bytea,bytea)', 'mcp_check_access(text,bytea,text)', 'mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)', 'mcp_find_people(text,bytea,text,text,text,text,text,text,text)', 'mcp_get_deal(text,bytea,text,text)', 'mcp_get_deal_checklists(text,bytea,text,text,boolean,text)', 'mcp_get_status(text,bytea,text)', 'mcp_list_all_deals(text,bytea,text,text,text,text,text)', 'mcp_list_deals(text,bytea,text,text,text,integer,text)', 'mcp_list_todos(text,bytea,text,text,text,text,text,boolean,boolean,text)', 'mcp_refresh(text,bytea,text,text,bytea,bytea)', 'mcp_register_client(text,text,text,text[],bytea)', 'mcp_remove_todo(text,bytea,text,text,text)', 'mcp_restore_todo(text,bytea,text,text,text)', 'mcp_update_todo(text,bytea,text,text,jsonb,text)', 'mcp_write_access(text,bytea,text)']::text[]) x),
    'anon_ai_app', (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname ~ '^ai_app_'
        AND has_function_privilege('anon', p.oid, 'EXECUTE')),
    'allowlist_key', (SELECT array_agg(a.attname::text ORDER BY a.attnum) FROM pg_constraint k JOIN pg_attribute a ON a.attrelid = k.conrelid AND a.attnum = ANY (k.conkey)
                       WHERE k.conrelid = 'public.mcp_redirect_allowlist'::regclass AND k.contype = 'p') = ARRAY['redirect_uri'],
    'ledger', (SELECT count(*) FROM supabase_migrations.schema_migrations WHERE version = '20261118180000')) INTO v;
  w_changed := CASE WHEN v ->> 'exchange_md5_before' = '9a33bff2db31288bd77a57489558a65b' THEN '[]'::jsonb ELSE jsonb_build_array('public.mcp_exchange_code(text,bytea,text,text,text,text,bytea,bytea)'::regprocedure::text) END;
  SELECT coalesce(jsonb_agg(x ORDER BY x COLLATE "C"), '[]') INTO w_added
    FROM unnest(ARRAY['public.ai_app_notice_claim(integer)'::regprocedure::text, 'public.ai_app_notice_done(uuid,integer,text,text)'::regprocedure::text]) x WHERE NOT EXISTS (SELECT 1 FROM pg_temp.pn_fn_before b WHERE b.sig = x);
  SELECT coalesce(jsonb_agg(x ORDER BY x COLLATE "C"), '[]') INTO w_rel
    FROM unnest(ARRAY['ai_app_connect_notices', 'ai_app_connect_notices_due_idx', 'ai_app_connect_notices_pkey', 'ai_app_connect_notices_user_idx']) x WHERE NOT EXISTS (SELECT 1 FROM pg_temp.pn_rel_before b WHERE b.rel = x);
  IF v ->> 'exchange_md5' IS DISTINCT FROM '9a33bff2db31288bd77a57489558a65b'
     OR v -> 'changed' IS DISTINCT FROM w_changed OR v -> 'added' IS DISTINCT FROM w_added OR v -> 'gone' IS DISTINCT FROM '[]'::jsonb
     OR (v ->> 'exchange_attributes_unchanged')::boolean IS NOT TRUE OR (v ->> 'jobs_owner_definer_path_grants')::boolean IS NOT TRUE
     OR (v ->> 'table_closed_columns_keys')::boolean IS NOT TRUE
     OR v -> 'rel_changed' IS DISTINCT FROM '[]'::jsonb OR v -> 'rel_gone' IS DISTINCT FROM '[]'::jsonb OR v -> 'rel_added' IS DISTINCT FROM w_rel
     OR (v ->> 'anon_mcp_17')::boolean IS NOT TRUE OR (v ->> 'anon_ai_app')::int IS DISTINCT FROM 0 OR (v ->> 'ledger')::int IS DISTINCT FROM 1
     OR (v ->> 'allowlist_key')::boolean IS NOT TRUE THEN
